def _inverse(raw, kind):
    pin=PINS[kind];digest=hashlib.sha256(raw).hexdigest()
    if digest==pin["parent"]:
        return raw
    if digest!=pin["current"]:
        raise RuntimeError("unreviewed merged AX capture source bytes")
    value=raw.decode("utf-8")
    for current,parent in pin["inverse"]:
        if value.count(current)!=1:
            raise RuntimeError("merged AX inverse hunk is not unique")
        value=value.replace(current,parent,1)
    result=value.encode("utf-8")
    if hashlib.sha256(result).hexdigest()!=pin["parent"]:
        raise RuntimeError("complete merged AX predecessor bytes differ")
    return result

def predecessor(raw):
    """Remove only the publication witness, retaining e30 canonical reuse."""
    return _inverse(raw,"publication")

def without_canonical(raw):
    """Remove only byte reuse, retaining the complete ab8 publication witness."""
    return _inverse(raw,"canonical")
